const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([38.602260, 7.578886]);
  const region = center.buffer(30000); // 30 km radius

  // 2. Data Acquisition - JRC Global Surface Water dataset
  const jrc = ee.Image('JRC/GSW1_4/GlobalSurfaceWater');
  const occurrence = jrc.select('occurrence');

  // Create water mask (permanent water with occurrence > 80%)
  const waterMask = occurrence.gt(80);

  // Convert to vectors to identify individual lakes
  const vectors = waterMask.reduceToVectors({
    geometry: region,
    scale: 1000,
    geometryType: 'polygon',
    eightConnected: false,
    labelProperty: 'water'
  });

  // Check if collection is empty
  const count = vectors.size().getInfo();
  if (count === 0) {
    console.log("No water bodies found in region.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate area for each feature and filter for lakes > 25 km²
  const lakes = vectors.map(function(feature) {
    const area = feature.area().divide(1000000); // Convert to km²
    return feature.set('area_km2', area);
  }).filter(ee.Filter.gt('area_km2', 25));

  const largeLakesCount = lakes.size().getInfo();

  // Validate result
  if (largeLakesCount === null || largeLakesCount === undefined || largeLakesCount < 0) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Output evidence
  console.log(`Total water bodies: ${count}`);
  console.log(`Lakes > 25 km²: ${largeLakesCount}`);

  // Final answer
  if (largeLakesCount > 2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
